  function go(route){if(route==='assessment'&&state.survey.result!=='C'){route='questionnaire';toast('补充考核仅在问卷进入后续安排后开放。');}const tab=currentTab();if(currentRoute()!==route){tab.history=tab.history.slice(0,tab.index+1);tab.history.push(route);tab.index=tab.history.length-1;}if(route==='forum')state.forumViewed=true;if(route==='rank'){state.rankViewed=true;if(state.survey.result)state.checklist.notice=true;}if(route==='assessment')state.assessmentOpened=true;if(route==='oldArchive')state.archiveVisited=true;if(route==='profile')state.profileViewed=true;if(route==='newsProject'){state.projectRead=true;state.ncutProjectViewed=true;}if(route==='newsMemorial'){state.memorialRead=true;state.ncutMemorialViewed=true;}state.activeApp='browser';state.error='';save();render();}
