    'next-step'(){state.step=Math.min(steps.length-1,state.step+1);save();render();},
    'prev-step'(){state.step=Math.max(0,state.step-1);save();render();},
    'save-form'(){save();toast('申请信息已保存为草稿。');},
    'save-survey'(){save();toast('问卷草稿已保存。');},
    'submit-survey'(){const a=state.survey.answers.map(Number);const missing=a.map((v,i)=>v?0:i+1).filter(Boolean);if(missing.length){toast(`请完成第 ${missing.join('、')} 题后再提交。`);return;}const D=a[0]+(6-a[1])+a[2]+(6-a[3]),E=a[4]+(6-a[5])+a[6]+(6-a[7]);state.survey.result=D>=16&&E>=16&&a[8]>=4&&a[9]>=4?'C':D>=16?'A':'B';if(state.rankViewed)state.checklist.notice=true;state.survey.versions+=1;save();render();toast('问卷已提交，回执已保留。');},
    'candidate-summary'(el){state.progressCandidate=el.dataset.candidate;save();go('candidateSummary');},
