    'generic-template'(){modal('<h2>项目经历填写模板（通用版）</h2><div class="template-preview"><p><b>1. 项目名称与时间</b></p><p><b>2. 本人承担的具体工作</b></p><p><b>3. 小组共同成果</b></p><p><b>4. 尚未完成或无法核实的内容</b></p><p class="small muted">当前通用版不含往届申请人信息。</p></div>','document-dialog','通用模板');},
