    'ask-tang'(){if(state.tangInquiryPending||state.tangAsked)return;state.tangInquiryPending=true;save();render();setTimeout(()=>{state.tangInquiryPending=false;state.tangAsked=true;state.oldAttachmentCorrected=true;state.selectedMail='attachmentReply';save();render();toast('唐敏已回复，当前附件已更换。');},1100);},
    'archive-placeholder'(el){const label=el.textContent.trim();toast('正在读取旧站附件…');setTimeout(()=>modal(`<h2>${escape(label)}</h2><div class="archive-file-preview"><p>公开附件索引已找到。</p><p>旧站迁移后部分页面图像尚未恢复，当前只保留文件名、年份和公开归档说明。</p><p class="small muted">该附件不包含个人申请材料；完整文件将在迁移完成后恢复。</p></div>`,'document-dialog','旧站附件'),650);},
