    'save-answer'(){if(!state.recoveryAnswer){toast('请先选择本人目前的确认情况。');return;}state.savedAnswer=true;const version=state.savedFiles.filter(f=>f.id.startsWith('my-revisit-note')).length+1;saveCopy(`my-revisit-note-${version}`,`夏令营活动记录_本人说明_RV-0922-071_${version}.txt`,`夏令营活动记录本人说明（本地留存）\n任务：RV-0922-071\n记录对象：陈言\n来源批次：HC26-JUL-02\n2026年9月22日\n版本：${version}\n\n${state.recoveryAnswer}\n\n说明按本人实际选择原样保存，此副本不修改之前保存的版本。`);state.selectedMail='forum';save();render();toast('本人说明已保存。邮箱收到交流区说明。');},
    'save-receipt'(){if(!state.submitted)return;saveCopy('submission-receipt','提交回执_RC-0922-071.txt',`本轮申请材料提交回执\n来源：https://xspt.hcu.example/sstm/tm/status\n取得时间：2026年9月22日 09:24\n提交时间：2026年9月22日 09:18\n回执编号：RC-0922-071\n\n申请人：陈言\n报名号：HC2026-0922-071\n申请状态：材料已提交，等待后续考核\n专业排名比例：${state.form.rank}%\n申请方向：${state.form.program}\n营期批次：${state.form.camp}\n成绩及排名证明：${findFile(state.form.file)?.name||''}\n\n上述字段与附件版本为本轮实际提交内容。`);},
    'save-rank'(){state.checklist.proof=true;saveCopy('progress-copy-0920','方向接收进度_2026-09-22_0920.txt','来源：https://xspt.hcu.example/sstm/tm/progress\n取得时间：2026年9月22日 09:24\n页面更新时间：2026年9月22日 09:20\n\n方向接收进度\n1 周亦成 拟接收展示\n2 林知远 拟接收展示\n3 许澄 拟接收展示\n4 邱然 拟接收展示\n5 顾宁 拟接收展示\n6 蒋思齐 拟接收展示\n7 陈言 候补顺位1\n8 赵可宁 候补顺位2\n9 程语安 候补顺位3\n10 宋惟真 候补顺位4\n\n本页为方向接收进度，最终结果以正式审核通知为准。');},
    'save-transcript'(){saveCopy('transcript-copy','夏令营活动记录_C-04_文字与来源.txt','来源：https://xspt.hcu.example/sstm/tm/revisit/0922\n取得时间：2026年9月22日 09:24\n任务：RV-0922-071\n条目编号：C-04\n来源批次：HC26-JUL-02\n归档日期：2026年7月13日\n记录对象：陈言\n\n陈言：我当时没有看到有人要求停止。\n\n页面说明：本条目为营期活动后复盘的导入片段，不代表完整访谈，也不代表后续招生考核回答。');},
    'open-reference'(el){const id=el.dataset.file;const granted=id==='ningchuan-project'?state.campusAccessProject:id==='ningchuan-memorial'?state.campusAccessMemorial:false;if(!granted){toast('请先在宁川理工大学“科研资料库”完成本篇服务码验证。');return;}if(id==='ningchuan-project'){state.projectRead=true;state.ncutProjectViewed=true;}if(id==='ningchuan-memorial'){state.memorialRead=true;state.ncutMemorialViewed=true;}save();showFile(id);},
    'campus-article'(el){state.campusArticleId=el.dataset.article;save();go('campusArticle');},
    'campus-service'(el){state.campusServiceKey=el.dataset.service||'0';save();go('campusService');},
    'campus-access'(){const value=($('#campus-pass')?.value||'').trim().toUpperCase(),codes={'nc-project':'JUL-02-11','nc-memorial':'JUL-02-06'},keys={'nc-project':'campusAccessProject','nc-memorial':'campusAccessMemorial'},required=codes[state.campusArticleId],key=keys[state.campusArticleId];if(!required||value!==required){toast('服务码无效，请根据办事服务说明核对格式。');return;}state[key]=true;save();render();toast('本篇资料的校内服务码验证通过。');},
    'ncut-search'(el){const requested=(el.dataset.query||document.querySelector('[data-ncut-search]')?.value||'').trim();state.ncutQuery=requested;state.campusKey='ningchuan';state.campusQuery=requested;save();go('campusSearch');},
    'campus-search'(el){const requested=(el.dataset.query||document.querySelector('[data-campus-search]')?.value||'').trim();state.campusQuery=requested;if(state.campusKey==='ningchuan')state.ncutQuery=requested;save();go('campusSearch');},
    'add-zhao'(){state.zhaoAdded=true;save();render();toast('已添加赵可宁。她不会收到你的材料副本。');},
    'zhao-question'(el){const followups=[['材料要求','你的通知里写了哪些材料？','落款是 9 月 22 日 09:20，附件栏只列《项目说明》。我没有收到其他材料要求，所以不敢把七月的文件再传一遍。'],['问卷进度','你问卷提交了吗？','还在做。交流区有人说会进入复核，但这类说法没法确认，先只留好自己的回执。'],['接收进度','你看到方向接收进度了吗？','看到了，我在候补第 2 位。页面里是普通的公开展示信息，先别根据名单推断什么。']];const q=followups[Number(el.dataset.question)];if(!q||state.zhaoTyping)return;state.zhaoMessages.push({side:'mine',text:q[1]});state.zhaoTyping=true;save();render();setTimeout(()=>{state.zhaoMessages.push({side:'other',text:q[2]});state.zhaoQuestionStage+=1;state.zhaoTyping=false;save();render();},850);},
    'lzy-prompt'(){state.lzyPrompted=true;save();render();},
