    'lzy-identity'(){state.lzyIdentityAsked=true;save();render();},
    'submit-identity'(){if(!((state.ncutProjectViewed||state.projectRead)&&(state.ncutMemorialViewed||state.memorialRead))){toast('请先核对两份来源独立的公开资料。');return;}if(state.identityConclusion!=='same'){toast(state.identityConclusion==='name'?'姓名本身不足以确认身份，请核对院系、项目和职责。':'现有资料不足以确认账号操作者，请仅提交可证实的资料来源疑问。');return;}state.identityReported=true;state.rosterCorrected=true;saveCopy('identity-check-receipt','资料来源核对回执_HC-014.txt','资料来源核对回执\n来源：https://admission.hcu.example/2027/records/check\n提交时间：2026年9月22日 10:02\n核对对象：HC-014\n\n提交时展示字段快照\n姓名：林知远\n本科院校 / 院系：宁川理工大学 / 自动化学院\n项目经历：轮式巡检平台多传感器定位\n项目职责：负责人\n关联交流账号：LZY-014\n\n本人说明：当前展示资料与已故者的院校、项目经历及职责对应，需要说明资料来源。\n\n系统回执：已收到资料来源疑问。候补资格状态不因本次提交即时变化。');state.selectedMail='correction';save();render();toast('资料来源疑问已提交。邮箱收到处理通知。');},
    back(){const tab=currentTab();if(tab.index>0)tab.index--;save();render();},
    forward(){const tab=currentTab();if(tab.index<tab.history.length-1)tab.index++;save();render();},
    refresh(){save();render();toast('页面已刷新。');},
    'new-tab'(){if(state.tabs.length>=5){toast('最多保留5个标签页。');return;}state.tabs.push({history:['blank'],index:0});state.activeTab=state.tabs.length-1;save();render();},
    'select-tab'(el){state.activeTab=Number(el.dataset.tab);save();render();},
    'close-tab'(el){if(state.tabs.length===1)return;const i=Number(el.dataset.tab);state.tabs.splice(i,1);if(state.activeTab>i)state.activeTab--;else if(state.activeTab>=state.tabs.length)state.activeTab=state.tabs.length-1;save();render();},
    history(){const items=[...new Set(state.tabs.flatMap(t=>t.history))].filter(r=>r!=='blank');modal(`<h2>浏览历史</h2><div class="history-list">${items.map(r=>`<button data-action="history-route" data-route="${r}">${routeLabel(r)}<small>${routePath(r)}</small></button>`).join('')}</div>`,'','浏览历史');},
